create or replace function public.cpcm_delete_archived_account(target_account_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare a public.accounts%rowtype; begin select * into a from public.accounts where id=target_account_id for update; if not found then return jsonb_build_object('ok',true,'deleted',false,'already_missing',true); end if; if a.archived_at is null then raise exception 'Only archived accounts may be permanently deleted'; end if; delete from public.accounts where id=target_account_id and archived_at is not null; return jsonb_build_object('ok',true,'deleted',true,'account_id',target_account_id); end; $$;
create or replace function public.cpcm_delete_archived_portfolio(target_portfolio text, expected_count integer default null) returns jsonb language plpgsql security invoker set search_path=public as $$ declare actual_count integer; deleted_count integer; begin if target_portfolio is null or btrim(target_portfolio)='' then raise exception 'Portfolio required'; end if; perform 1 from public.accounts where archived_at is not null and portfolio=target_portfolio for update; select count(*) into actual_count from public.accounts where archived_at is not null and portfolio=target_portfolio; if actual_count=0 then return jsonb_build_object('ok',true,'deleted_count',0,'already_empty',true); end if; if expected_count is not null and actual_count<>expected_count then raise exception 'Archived portfolio changed during confirmation. Expected %, found %',expected_count,actual_count; end if; delete from public.accounts where archived_at is not null and portfolio=target_portfolio; get diagnostics deleted_count=row_count; if deleted_count<>actual_count then raise exception 'Delete verification failed'; end if; return jsonb_build_object('ok',true,'deleted_count',deleted_count,'portfolio',target_portfolio); end; $$;
